{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 개선 경험을 통해 데이터베이스 조회 병목을 근거로 진단하고, 원인에 맞는 변경을 적용한 뒤 비교 가능한 측정으로 성능 개선 효과를 확인했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회에 3.2초가 걸렸던 상황과 당시 조회 조건 및 데이터 접근 구조를 설명한다.",
          "task": "본인이 맡은 조회 성능 개선 범위와 확인해야 했던 병목을 설명한다.",
          "action": "실행 계획, 로그 또는 호출 구조에서 확인한 병목 근거와 인덱스 추가·조인 정리가 그 원인을 어떻게 줄였는지 설명한다. 변경 전후의 측정 조건과 방법도 제시한다.",
          "result": "3.2초에서 0.4초로 줄어든 결과를 제시하고, 조회 조건·데이터 규모·반복 측정 등 비교에 영향을 주는 조건을 어떻게 맞추거나 고려했는지 설명한다."
        },
        "expectedEvidence": [
          "조회 조건과 테이블 접근 방식 등 병목을 이해할 수 있는 구체적인 조회 구조",
          "실행 계획, 로그 또는 호출 구조에서 관찰한 내용과 병목 원인의 연결",
          "추가한 인덱스와 변경한 조인 내용이 해당 병목을 줄이는 이유",
          "변경 전후 응답 시간 수치와 측정 방법 및 비교 조건"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄일 때, 어디가 느린지 어떻게 찾았고 변경 효과는 어떤 조건에서 확인했나요?",
      "answerTip": "당시 상황부터 차근차근 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "조회 구조와 실행 계획·로그·호출 구조의 구체적인 관찰 내용을 연결해 병목 원인을 설명한다.",
            "인덱스와 조인을 무엇 때문에 어떻게 바꿨는지 설명하며, 변경 내용이 진단한 병목과 부합한다.",
            "개선 전후 수치를 제시하고 측정 방법과 비교 조건을 설명해 개선 효과를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 병목을 뒷받침하는 관찰 근거와 개선 방법의 연결은 설명하지만, 조회 구조나 변경 내용의 일부가 구체적이지 않다.",
            "개선 전후 수치와 측정 방법은 제시하지만, 데이터 규모나 조회 조건 등 비교 조건에 대한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "병목을 확인한 근거 없이 쿼리가 느렸다는 설명이나 일반적인 최적화 방법만 나열한다.",
            "인덱스 추가·조인 변경과 병목 원인의 관계를 설명하지 못한다.",
            "개선 전후 수치 또는 측정 방법을 제시하지 못해 성능 개선 효과를 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 알림 중복 발송 경험을 통해 로그와 운영 지표로 원인 가설을 좁히고, 서비스 복구와 재발 방지를 구분해 수행했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 배포 다음 날 알림이 두 번 발송된다는 문의가 들어온 상황과 확인한 오류 현상을 설명한다.",
          "task": "중복 발송 원인을 찾아 정상 발송을 회복하고 같은 장애의 반복을 막기 위해 본인이 담당한 범위를 설명한다.",
          "action": "시간순 로그와 확인한 운영 지표가 있다면 이를 바탕으로 클라이언트 문제라는 초기 가설을 어떻게 검토하고 두 서버의 스케줄러 중복 실행으로 원인을 좁혔는지 설명한다. 잠금 키 적용 등 복구 조치와 배포 체크리스트 보완 등 재발 방지 조치를 구분한다.",
          "result": "조치 후 로그나 발송 현황을 통해 중복 실행·발송이 해소됐는지 확인한 방법과 이후 배포에서 재발 방지 조치를 적용한 내용을 설명한다."
        },
        "expectedEvidence": [
          "중복 발송 현상을 추적한 로그 또는 모니터링 관찰 내용과 확인 순서",
          "관찰 근거를 통해 초기 가설을 검토하고 두 서버의 스케줄러 중복 실행으로 원인을 좁힌 과정",
          "잠금 키 적용 등 복구 조치가 중복 실행을 막는 방식과 정상화 확인 근거",
          "당장의 복구와 구분되는 재발 방지 조치 및 동일 원인의 반복을 막는 연결 관계"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림이 중복 발송됐을 때, 원인을 어떻게 좁혔고 서비스를 정상화한 뒤 같은 문제가 반복되지 않도록 무엇을 바꿨나요?",
      "answerTip": "당시 상황부터 차근차근 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그나 운영 지표에서 확인한 구체적인 내용과 조사 순서를 제시하고, 이를 근거로 초기 가설에서 스케줄러 중복 실행으로 원인을 좁힌 과정을 설명한다.",
            "복구 조치가 두 서버의 중복 실행을 어떻게 막았는지 설명하고, 로그나 발송 현황으로 정상화를 확인한 근거를 제시한다.",
            "복구 조치와 재발 방지 조치를 구분하며, 체크리스트 등의 변경이 같은 원인의 반복을 어떻게 방지하는지 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그 등 관찰 근거를 바탕으로 스케줄러 중복 실행을 찾은 과정은 설명하지만, 초기 가설을 배제하거나 원인을 좁힌 세부 과정이 부족하다.",
            "복구 방식과 정상화 확인 방법을 설명하지만, 확인한 내용이 구체적이지 않다.",
            "복구와 별도로 재발 방지 조치를 제시하지만, 이후 적용 내용이나 동일 원인 방지와의 연결 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "로그나 지표의 관찰 내용 없이 스케줄러 문제였다는 결론만 제시한다.",
            "복구 조치가 중복 실행을 막는 방식 또는 정상화 확인 방법을 설명하지 못한다.",
            "즉시 수정한 내용만 반복하거나 주의하겠다는 수준에 그쳐, 같은 장애를 막을 별도의 조치를 제시하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "세탁소 인터뷰에서 수집한 요청의 목적과 범위를 정리하고, 포함·제외 항목과 우선순위, 예외 조건을 요구사항 정의서에 담아 개발·디자인의 구현 범위를 합의할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 5곳의 인터뷰에서 나온 요청 중 정리가 필요했던 구체적인 사례와 요청 배경을 설명한다.",
          "task": "기획 담당자로서 해결할 문제와 구현 범위를 정하고, 팀원이 같은 내용을 이해할 수 있도록 요구사항을 문서화해야 했던 과제를 설명한다.",
          "action": "요청의 목적을 확인하고 포함·제외 항목, 우선순위와 예외 조건을 요구사항 정의서에 작성한 뒤, 개발 담당 팀원과 범위를 조정한 과정을 설명한다.",
          "result": "최종적으로 합의한 구현 범위와 보류한 항목이 무엇이며, 합의 내용을 문서에 어떻게 남겼는지 설명한다."
        },
        "expectedEvidence": [
          "인터뷰에서 나온 실제 요청과 그 요청으로 해결하려던 문제의 연결",
          "요구사항 정의서에 기록한 포함·제외 항목과 구분 이유",
          "요구사항의 우선순위와 그 순서를 정한 이유",
          "요구사항에 반영한 예외 조건과 처리 방침",
          "개발 담당 팀원과 조정한 쟁점, 최종 합의 범위 및 문서 반영 내용"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 요청을 어떤 문서로 정리했고, 개발 담당 팀원과 무엇을 만들기로 결정했는지 실제 사례로 설명해 주세요.",
      "answerTip": "한 가지 사례를 중심으로 차근차근 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 요청과 해결 목적을 연결하고, 문서에 담은 포함·제외 항목과 우선순위의 이유를 구체적으로 설명한다.",
            "요구사항에 해당하는 예외 조건과 처리 방침을 실제 문서 내용 수준으로 설명한다.",
            "개발 담당 팀원과의 조정 전후 범위, 최종 합의 내용과 문서 반영 방식을 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실제 요청의 목적과 주요 구현 범위는 설명하지만, 포함·제외 항목이나 우선순위의 이유 중 일부가 불명확하다.",
            "예외 조건을 언급하나 처리 방침이나 문서에 기록한 내용이 구체적이지 않다.",
            "개발 담당 팀원과 합의한 주요 내용은 설명하지만, 조정 과정이나 최종 문서 반영 내용이 일부 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "요청을 모았다는 설명에 그쳐 해결 목적과 구현 범위를 확인하기 어렵다.",
            "포함·제외 항목, 우선순위와 예외 조건을 문서로 구체화한 근거가 대부분 없다.",
            "개발 담당 팀원에게 전달했다는 설명만 있고, 무엇을 조정하고 합의했는지 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예약 취소 흐름을 화면 단위로 구체화하고, 상태 변화와 예외 상황, 안내 문구를 개발·디자인이 구현할 수 있는 화면설계서로 작성했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스에서 설계한 예약 취소 사례와 사용자가 취소를 시도하는 화면의 시작 상태를 설명한다.",
          "task": "기획 담당자로서 취소 과정의 화면 이동, 상태 변화와 상황별 안내를 화면설계서에 정의해야 했던 과제를 설명한다.",
          "action": "Figma 화면설계서에 사용자 조작에 따른 화면 이동과 상태 변화, 정상 처리와 예외 상황의 동작 및 안내 문구를 작성한 방법을 설명한다.",
          "result": "작성한 화면설계서를 따라 취소 전부터 처리 후까지의 화면과 동작을 설명하고, 화면 간 조건이나 안내에 모순이 없는지 보여준다."
        },
        "expectedEvidence": [
          "취소 시작부터 처리 후까지 이어지는 화면 순서와 화면 간 이동 조건",
          "사용자 조작에 따른 화면 상태와 버튼 등 구성 요소의 변화",
          "정상 처리와 구분되는 구체적인 예외 상황 및 해당 화면의 처리 방식",
          "각 상황에 표시하는 안내 문구와 이후 가능한 사용자 행동",
          "화면설계서에서 화면, 조건, 동작을 연결해 개발·디자인이 해석할 수 있도록 작성한 구체적인 내용"
        ]
      },
      "question": "동네 세탁소 예약 서비스에서 예약 취소 시 사용자가 보게 되는 화면과 안내를 Figma 화면설계서에 어떻게 담았는지, 실제 작성한 한 사례로 설명해 주세요.",
      "answerTip": "기억나는 사례 하나를 차근차근 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "취소 시작부터 처리 후까지 화면 순서와 이동 조건을 연결하고, 사용자 조작에 따른 상태와 구성 요소의 변화를 구체적으로 설명한다.",
            "실제 설계한 예외 상황의 처리 방식, 안내 문구와 이후 가능한 행동을 서로 일치하게 설명한다.",
            "화면설계서에 기록한 조건과 동작을 제시해, 개발·디자인이 추가 해석 없이 해당 흐름을 구현할 수 있는 수준임을 보여준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "주요 화면 순서와 정상 처리 흐름은 설명하지만, 이동 조건이나 일부 화면 상태 변화가 빠져 있다.",
            "예외 상황과 안내를 설명하지만, 정확한 처리 방식이나 이후 사용자 행동 중 일부가 불명확하다.",
            "화면설계서에 작성한 내용은 확인되지만, 일부 조건이나 동작은 구현 전에 추가 확인이 필요하다."
          ]
        },
        "poor": {
